with ranked as (select id, supplier_name, city, rating from (select *, row_number() over (partition by country order by rating desc nulls last, id asc) as rn from suppliers) x where rn = 1) select case when rating >= 3.5 then 'LARGE' else 'SMALL' end as rating_tier, count_if(city = 'Chiang Mai') as chiang_mai_events, count(distinct city) as distinct_cities, sort_array(collect_set(city)) as city_list, count(*) as num_rows from ranked group by 1 order by rating_tier asc nulls last
